// Rehype plugin: optimizes every <img> rendered from blog post markdown
// content (the `![alt](path)` inline images) -- these were previously
// plain, eager, unoptimized JPEGs, unlike the hero image which already
// gets a WebP <picture> + lazy loading. Rewrites local /images/ sources to
// their .webp sibling (generated by scripts/generate-webp.mjs, which now
// also scans inline markdown images, not just frontmatter) and adds
// loading="lazy" + decoding="async" since these are always below the fold.
import { visit } from 'unist-util-visit';

export default function rehypeOptimizeImages() {
  return (tree) => {
    visit(tree, 'element', (node) => {
      if (node.tagName !== 'img') return;
      const src = node.properties?.src;
      if (typeof src === 'string' && /^\/images\/.+\.(jpe?g|png)$/i.test(src)) {
        node.properties.src = src.replace(/\.(jpe?g|png)$/i, '.webp');
      }
      node.properties.loading = 'lazy';
      node.properties.decoding = 'async';
    });
  };
}
